@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  /* the summary takes focus by script when errors arrive (tabindex -1); its radius follows the Alert */
  .nz-form-summary {
    border-radius: var(--nz-radius-lg);
  }

  .nz-form-summary-list {
    display: flex;
    flex-direction: column;
    gap: var(--nz-space-1);
    margin: 0;
    padding-inline-start: var(--nz-space-4);
  }

  /* an error, not a decoration: critical text and an underline, so it never reads by colour alone */
  .nz-form-summary-link {
    border-radius: var(--nz-radius-xs);
    color: var(--nz-form-summary-link-fg, var(--nz-text-critical));
    text-decoration: underline;
    text-underline-offset: var(--nz-space-1);

    @media (hover: hover) {
      &:hover {
        text-decoration-thickness: 2px;
      }
    }
  }
}
